import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { id4Schema, type Id4 } from "./unions/id4.js";

export type ResponsesCustomToolCall = {
  /** The type of the custom tool call. Always `custom_tool_call`. @default "custom_tool_call" */
  type?: "custom_tool_call";
  /** An identifier used to map this custom tool call to a tool call output. */
  callId: string;
  /** The name of the custom tool being called. */
  name: string;
  /** The input for the custom tool call generated by the model. */
  input: string;
  /** The unique ID of the custom tool call. */
  id?: Id4;
};

export const responsesCustomToolCallSchema: Schema<ResponsesCustomToolCall> =
  s.object<ResponsesCustomToolCall>({
    type: s.defaulted(s.literal("custom_tool_call"), "custom_tool_call"),
    callId: s.string(),
    name: s.string(),
    input: s.string(),
    id: s.optional(s.lazy(() => id4Schema)),
    _keysMap: {
      callId: "call_id",
    },
  });
